using System;using System.IO;using UnityEngine;using UnityEditor;
namespace IslandGame.Diorama.Editor {
 public static class DioramaGroundPalette {
  [MenuItem("Island/Diorama/Generate separate ground palette")]
  static void MenuGenerate(){Generate();}
  public static object Generate(){var prefab=Resources.Load<GameObject>("NatureAuthoredMap");var terrain=prefab.GetComponentInChildren<Terrain>(true);if(!terrain)throw new Exception("Authored terrain missing");var source=terrain.terrainData;string path="Assets/DioramaPreview/Resources/DioramaTerrain.asset";var copy=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(!copy){copy=UnityEngine.Object.Instantiate(source);AssetDatabase.CreateAsset(copy,path);}var layers=source.terrainLayers;
   for(int i=0;i<layers.Length;i++){string layerPath="Assets/DioramaPreview/Settings/GroundLayer"+i+".terrainlayer";var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>(layerPath);if(!layer){layer=UnityEngine.Object.Instantiate(layers[i]);AssetDatabase.CreateAsset(layer,layerPath);}var texture=layers[i].diffuseTexture;if(texture){var rt=RenderTexture.GetTemporary(512,512,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);Graphics.Blit(texture,rt);var old=RenderTexture.active;RenderTexture.active=rt;var pixels=new Texture2D(512,512,TextureFormat.RGBA32,false);pixels.ReadPixels(new Rect(0,0,512,512),0,0);pixels.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);var colors=pixels.GetPixels();for(int n=0;n<colors.Length;n++){var c=colors[n];float l=c.r*.2126f+c.g*.7152f+c.b*.0722f;var toned=Color.Lerp(c,new Color(l,l,l,c.a),.48f);colors[n]=toned*new Color(.87f,.82f,.70f,1);}pixels.SetPixels(colors);pixels.Apply();string texPath="Assets/DioramaPreview/Resources/GroundPalette"+i+".png";File.WriteAllBytes(texPath,pixels.EncodeToPNG());UnityEngine.Object.DestroyImmediate(pixels);AssetDatabase.ImportAsset(texPath);var importer=(TextureImporter)AssetImporter.GetAtPath(texPath);importer.isReadable=false;importer.wrapMode=TextureWrapMode.Repeat;importer.mipmapEnabled=true;importer.maxTextureSize=512;importer.SaveAndReimport();layer.diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);}layers[i]=layer;EditorUtility.SetDirty(layer);}
   copy.terrainLayers=layers;EditorUtility.SetDirty(copy);AssetDatabase.SaveAssets();return new{layers=layers.Length,heightsUnchanged=true,originalTexturesChanged=false};
  }
 }
}
